create function pg_temp.task_snapshot() returns jsonb language sql as $$select jsonb_build_object(
 'tasks',(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by id),''))from operational_tasks t),
 'revisions',(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by id),''))from operational_task_revisions t),
 'enrollments',(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by id),''))from operational_task_enrollments t),
 'coverage',(select md5(coalesce(string_agg(to_jsonb(t)::text,'|' order by template_id,use_id,use_version),''))from operational_task_use_coverage t))$$;
insert into task_fixture values('before-failure',pg_temp.task_snapshot());
create temp table fault_count(value integer);insert into fault_count values(0);
create function pg_temp.fail_second_generated() returns trigger language plpgsql as $$begin
 if new.event='generated' and current_setting('lrv.operational_run',true)='74000000-0000-4000-8000-000000000005' then
  update fault_count set value=value+1;
  if(select value from fault_count)>=2 then raise exception 'Synthetic later-source fault must roll back earlier source';end if;
 end if;return new;end $$;
create trigger z_synthetic_reconciliation_fault after insert on operational_task_revisions for each row execute function pg_temp.fail_second_generated();
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into task_fixture select 'failure-start',start_operational_reconciliation_run('74000000-0000-4000-8000-000000000005',25);
insert into task_fixture select 'failure-result',execute_operational_reconciliation_run('74000000-0000-4000-8000-000000000005',25);
select is((select value->>'outcome' from task_fixture where key='failure-result'),'failed','Later-source transaction fault gets terminal failure');
select is((select value->>'failure_code' from task_fixture where key='failure-result'),'batch_transaction_rolled_back','Private error details replaced by safe failure code');
select is((select value->'counts' from task_fixture where key='failure-result'),'null'::jsonb,'Rolled-back batch does not report partial success counts');
select is(execute_operational_reconciliation_run('74000000-0000-4000-8000-000000000005',25),(select value from task_fixture where key='failure-result'),'Failed UUID never executes again');
reset role;
select is(pg_temp.task_snapshot(),(select value from task_fixture where key='before-failure'),'Earlier-source tasks, revisions, enrollment and coverage fully rolled back');
select is((select value from fault_count),0,'Fault fixture confirms its first generated row rolled back');
select is((select checkpoint_version from operational_reconciliation_cursor),(select (value->>'checkpoint_version')::integer from task_fixture where key='failure-start'),'Failure preserves original checkpoint');
drop trigger z_synthetic_reconciliation_fault on operational_task_revisions;
